// main/cc_fonts.h — application fonts and the glyph-coverage policy.
//
// Fonts (generated by tools/gen_cc_fonts.sh from Noto Sans SC Medium, OFL):
//   cc_fonts.body   16 px, ASCII + full GB2312 + common symbols: all dynamic text
//   cc_fonts.small  12 px, ASCII + UI symbols: fixed English labels and hints
//   cc_fonts.title  20 px, ASCII + UI symbols, falls back to body for Chinese
//   cc_fonts.num    40 px digits: pairing passkey
//   cc_fonts.icon   Montserrat 14: LV_SYMBOL_* icons only
//
// Dynamic text from the bridge passes through cc_fonts_set_text(), which
// replaces any code point the label's font chain cannot draw with U+25A1 (a
// deliberate, documented replacement) instead of LVGL's placeholder box.
#pragma once

#include <stddef.h>

#include "lvgl.h"

typedef struct {
    const lv_font_t *body;
    const lv_font_t *small;
    const lv_font_t *title;
    const lv_font_t *num;
    const lv_font_t *icon;
} cc_fonts_t;

extern cc_fonts_t cc_fonts;

// Call once after LVGL is initialized, before creating labels.
void cc_fonts_init(void);

// Glyph check over the font and its fallback chain (not the placeholder).
bool cc_fonts_has_glyph(const lv_font_t *font, uint32_t cp);

// Filter text against a font chain into out (see cc_text_filter_glyphs).
void cc_fonts_filter(const lv_font_t *font, const char *text, char *out, size_t cap);

// Set label text after filtering it against the label's actual font.
// LVGL task (or bsp_lvgl_lock() held) only.
void cc_fonts_set_text(lv_obj_t *label, const char *text);

// Boot check: logs U+XXXX for any required glyph that is missing and returns
// the count. A known-absent code point must stay absent (guards the check).
size_t cc_fonts_self_test(void);
